public class RtlDetector extends Detector implements XmlScanner {
    private static final String LEFT = "left";
    private static final String RIGHT = "right";

    static final Issue RTL_SYMMETRY = Issue.create(
        "RtlSymmetry",
        "Padding and margin symmetry",
        "If you specify padding or margin on the left side of a layout, you should probably also specify padding on the right side (and vice versa) for right-to-left layout symmetry.",
        Category.RTL,
        5,
        Severity.WARNING,
        new Implementation(RtlDetector.class, Scope.RESOURCE_FILE_SCOPE));

    @Override
    public Collection<String> getApplicableAttributes() {
        return Arrays.asList(
            SdkConstants.ATTR_PADDING_LEFT,
            SdkConstants.ATTR_PADDING_RIGHT,
            SdkConstants.ATTR_LAYOUT_MARGIN_LEFT,
            SdkConstants.ATTR_LAYOUT_MARGIN_RIGHT
        );
    }

    @Override
    public void visitAttribute(@NonNull XmlContext context, @NonNull Attr attribute) {
        String name = attribute.getLocalName();
        if (name == null) return;
        if (name.endsWith(LEFT)) {
            String base = name.substring(0, name.length() - LEFT.length());
            String counterpart = base + RIGHT;
            String genericHorizontal = base + "Horizontal"; // e.g. paddingHorizontal, layout_marginHorizontal
            checkPair(context, attribute, base, counterpart, genericHorizontal);
        } else if (name.endsWith(RIGHT)) {
            String base = name.substring(0, name.length() - RIGHT.length());
            String counterpart = base + LEFT;
            String genericHorizontal = base + "Horizontal";
            checkPair(context, attribute, base, counterpart, genericHorizontal);
        }
    }

