public static int getFolderVersion(String name) {
    int index = name.indexOf("-v");
    if (index != -1) {
        int end = index + 2;
        while (end < name.length()) {
            char c = name.charAt(end);
            if (!Character.isDigit(c)) break;
            end++;
        }
        if (end > index + 2) {
            try {
                return Integer.parseInt(name.substring(index + 2, end));
            } catch (NumberFormatException e) {}
        }
    }
    return -1;
}

